"""One-time chapter reconstruction; preserves every original deck and slide id.
Read the frozen authorized baseline, not a progressively modified chapter.
"""
from pathlib import Path
import hashlib
import html
import re

root = Path(__file__).resolve().parents[2]
baseline = (root/'docs/reviews/ch22-ch23-ch24-baseline/ch22.html').read_text()
target = root/'chapters/ch22.html'
if target.read_text() != baseline:
    raise SystemExit('Chapter differs from authorized baseline; inspect before overwriting.')
sections = re.findall(r'<section>([\s\S]*?)</section>', baseline)
decks = re.findall(r'<figure class="deck">[\s\S]*?</figure>', baseline)

def bi(zh, en, tag='p'):
    return f'<div class="bilingual"><div class="lang-zh"><{tag}>{zh}</{tag}></div><div class="lang-en"><{tag}>{en}</{tag}></div></div>\n'
def heading(zh, en, n=2):
    return f'<h{n}><span class="lang-zh">{zh}</span><span class="lang-en">{en}</span></h{n}>\n'
def snippet(source, label, kind='pseudocode', marker=None):
    text=(root/'examples/ch22'/source).read_text()
    if marker:
        text=text.split('// BEGIN PAGE '+marker+'\n')[1].split('// END PAGE '+marker)[0]
        text='\n'.join(line[4:] if line.startswith('    ') else line for line in text.splitlines()).strip()+'\n'
    return f'<pre data-language="{label}" data-kind="{kind}" data-source="{source}"'+(f' data-region="{marker}"' if marker else '')+f'><code>{html.escape(text.rstrip())}</code></pre>\n'

# Local semantic fixes; no group, frame, title id, or desc id is removed.
decks[0]=decks[0].replace('1. write v2 / read v2','PUT bytes / GET version').replace('2. durable receipt / bytes','receipt / checked bytes').replace('3. publish / resolve','PUT publish / GET resolve').replace('4. committed / manifest','commit / pinned manifest')
decks[0]=decks[0].replace('Data and Metadata round trips remain as the protocol.', 'PUT visits Data before Metadata; GET resolves Metadata before Data. These are separate operation orders.')
decks[0]=decks[0].replace('先画名字入口。bucket/key 可被覆盖，每次写分配新的不可变 v2；请求身份与版本身份分开，旧版字节不原地修改。','先画名字入口。bucket/key 可被覆盖，每次写分配新的不可变 v2。图逐步增加参与者，不给 GET 套用 PUT 的先后次序。')
decks[0]=decks[0].replace('Start at the named API. A bucket/key can be overwritten; each write allocates immutable v2. Request identity and version identity differ. Old bytes are never edited in place.','Start at the named API. Each overwrite allocates immutable v2. The deck adds actors; GET does not follow the PUT order.')
decks[1]=decks[1].replace('read / append by offset','read sealed records').replace('checked record / receipt','verified record bytes').replace('x="75" y="291"','x="28" y="291"')
decks[1]=decks[1].replace('Data appends records to Pack A or reads by offset; Pack A replies to Data with a checked record or receipt.','Data reads sealed Pack A by offset; verified record bytes return to Data. New appends use a separate writable pack.')
decks[1]=decks[1].replace('A sealed pack accepts no more appends.','A sealed pack accepts no more appends.').replace('Pack one million 10 KB objects: 10 GB logical, about 10 packs at a 1 GB target. Directory and inode work falls; random data reads may still hit disk.','About ten 1 GB packs hold one million 10 KB objects. This picture reads sealed A; fresh appends use another writable pack. Random reads may still hit disk.')
decks[1]=decks[1].replace('把一百万个 10 KB 对象打包，逻辑字节是 10 GB。若目标 pack 为 1 GB，约 10 个 pack；减少目录与 inode，不保证随机读不碰盘。','一百万个 10 KB 对象约用十个 1 GB pack。图中读取已 seal 的 A；新追加进入另一可写 pack。减少目录与 inode，不保证随机读不碰盘。')
decks[2]=decks[2].replace('three independent placement domains','three separate placement domains')
old='<rect x="160" y="42" width="230" height="328" rx="12" class="box"/><text x="275" y="203" text-anchor="middle" class="label">Data</text><text x="275" y="222" text-anchor="middle" class="sub">encode / decode / repair</text>'
new='<rect x="160" y="165" width="190" height="85" rx="12" class="box"/><text x="255" y="204" text-anchor="middle" class="label">Data</text><text x="255" y="223" text-anchor="middle" class="sub">encode / decode / repair</text><path d="M350 205 H390 M390 55 V351" class="wire"/><text x="275" y="147" text-anchor="middle" class="tiny">one service, fragment ports</text>'
assert decks[3].count(old)==5
decks[3]=decks[3].replace(old,new).replace('old B0: checksum mismatch','Data rejects B0 checksum')
decks[3]=decks[3].replace('A checksum-failure reply from the old B0 node arrives at Data.','B0 returns corrupt bytes and Data detects the mismatch locally; the left spine represents Data ports, not another component.')
decks[3]=decks[3].replace('Verified replies from B1 through B4 feed decoding.','Verified replies from B1 through B4 feed decoding.').replace('B5 is an unused survivor.','B5 is an unused survivor; its path is muted in this repair example.')
# In the fault frame, the unused B5 round trip is explicitly muted.
frames=re.findall(r'<div class="slide">[\s\S]*?</div>',decks[3])
last=frames[-1]
last=last.replace('<path d="M390 335 L655 335" class="wire"/>','<path d="M390 335 L655 335" class="wire muted"/>').replace('<polygon points="665,335 655,340 655,330" class="head"/>','<polygon points="665,335 655,340 655,330" class="head muted"/>').replace('<path d="M665 351 L400 351" class="wire reply"/>','<path d="M665 351 L400 351" class="wire reply muted"/>').replace('<polygon points="390,351 400,346 400,356" class="head reply"/>','<polygon points="390,351 400,346 400,356" class="head reply muted"/>')
decks[3]=decks[3].replace(frames[-1],last)
decks[5]=decks[5].replace('A red request from API to Metadata marks abort competing for OPEN through CAS; the normal metadata reply reports the winner.','The red abort annotation describes a competing CAS over the existing API-to-Metadata request path; the normal reply reports the winner.')
decks[5]=decks[5].replace('Fenced ABORTED sessions are swept after the lease expires.','Authority fences ABORTED first; Data closes old writes, drains admitted writers, and sweeps when protected leases have drained.').replace('ABORTED lease expires → fence + sweep','ABORTED: fenced → Data drain → sweep')
decks[5]=decks[5].replace('OPEN → FINALIZING → COMPLETED(version)','OPEN → FINALIZING → COMPLETED / REJECTED')

out=baseline[:baseline.index('<section>')]
out=out.replace('约 40 分钟','约 35 分钟').replace('~40 min','~35 min')
out+='<section>'+heading('本章主线：名字、版本、字节各由谁负责','The thread: authority over names, versions, and bytes')
out+=bi('先讲闭合的<strong>上传 → 发布 → 固定版本读取 → 逻辑删除 → 物理回收</strong>；22.6 再把上传拆成并发 parts。中间四组保留演示分别回答小对象打包、三副本、纠删码和名字分片怎样改变成本。','Walk through <strong>upload → publication → pinned-version read → logical deletion → physical cleanup</strong>, then split uploads into concurrent parts in 22.6. The other four preserved decks explain packing, replication, erasure coding, and name sharding.')
out+=bi('范围是单地域、允许覆盖和保留版本的对象 API。Metadata 决定 tenant/bucket/key 的权限、current、上传状态与原结果；Data 保存不可变字节、校验和冗余。Metadata 成功必须同时有完整 Data 回执和已提交的名字；上传超时只表示结果未知。','The scope is a one-region object API with overwrites and retained versions. Metadata owns scope authorization, current, upload state, and saved results; Data owns immutable bytes, checksums, and redundancy. Success needs both a complete Data receipt and committed naming metadata. Upload timeout is an unknown outcome.')
out+=heading('先确认三项契约','Three contracts to settle',3)
out+=bi('<strong>读什么：</strong>无版本 GET 解析 current 并固定一个版本，显式版本读仍须鉴权。<strong>成功什么：</strong>本设计单键线性化；多片 LIST 无共同快照，弱于公开 S3。<strong>删什么：</strong>delete marker 只改变名字，保留版本、读租约和未决上传分别保护字节。<a href="#ref-1">[1]</a><a href="#ref-9">[9]</a>','<strong>Read:</strong> resolve current once or authorize an explicit version. <strong>Success:</strong> single-key linearization, with a weaker LIST contract than public S3. <strong>Delete:</strong> a marker changes naming; retained versions, read leases, and unresolved uploads independently protect bytes. <a href="#ref-1">[1]</a><a href="#ref-9">[9]</a>')
out+='<details><summary><span class="lang-zh">教学假设与容量推导：100 PB、180 PB 和 API 21 台</span><span class="lang-en">Teaching assumptions and arithmetic: 100 PB, 180 PB, and 21 API boxes</span></summary>'
assumptions=sections[1][sections[1].index('<div class="bilingual"><div class="lang-zh"><p>下表'):]
out+=assumptions+'</details></section>\n'

out+='<section>'+heading('22.1 · 先落字节，原子发布，再按版本读','22.1 · Durable bytes, atomic publication, pinned reads')+decks[0]
out+=heading('三个身份，不能互相代替','Three identities with different jobs',3)
out+=bi('<code>name=(tenant,bucket_id,key 的原始字节)</code> 是可变入口；只规范化 bucket 身份，不擅自 trim、改大小写或归一化 key。<code>(name,principal,operation_id)</code> 认领一次请求；初始化在同片唯一约束下保存意图、upload_id 与 version_id，重试返回同一份身份。<code>(version_id,layout_generation,part_attempt_id)</code> 指定物理内容和布局；内容不变，压缩或重编码可以切到新布局。','<code>name=(tenant,bucket_id,exact key bytes)</code> is mutable. Normalize bucket identity without trimming, case-folding, or normalizing key bytes. A unique <code>(name,principal,operation_id)</code> claims the request and durably stores its intent, upload id, and version id. <code>(version_id,layout_generation,part_attempt_id)</code> identifies immutable content and its physical layout; compaction may change layout without changing the logical version.')
out+=bi('为把身份问题讲清，本示例初始化时已知长度和整对象 SHA-256，意图还绑定冗余策略及 expected_generation。换内容、目标、长度或前提不能复用同请求；接收未知长度流的协议需要另外冻结配额与最终校验契约。两个不同请求写同 key 分配不同版本；带相同 expected_generation 的竞争者只能一人发布，无条件写则按 Metadata 串行提交决定 current，不能按客户端时钟或 init 时刻排序。','This example knows length and whole-object SHA-256 at initialization and binds redundancy and expected_generation in the intent. A changed payload, target, length, or precondition needs a new request identity. Unknown-length streaming needs a separate quota/final-validation contract. Different requests allocate different versions. One matching-generation contender publishes; unconditional writes follow serialized Metadata publication rather than client clocks or initiation time.')
out+=heading('发布代码：一个名字分片里的真实原子边界','Publication: the actual atomic boundary on one name shard',3)
out+=bi('以下为 <strong>PG18 风格伪代码</strong>，输入认证 principal、初始化返回的 upload_id、冻结清单摘要和可信 Data 回执。Data 的 receipt 验证发生在事务外；它由受信服务签发，绑定精确字节身份、长度/摘要和放置代次，不能相信客户端报告“已上传”。版本行、current、upload 与固定结果共置一片；数据库事务不包住远端磁盘。<a href="#ref-10">[10]</a>','This <strong>PG18-style pseudocode</strong> accepts an authenticated principal, initialized upload id, frozen manifest hash, and trusted Data receipt. Data verification is outside the transaction. Its issuer binds exact bytes, size/digest, and placement generation; a client declaration is insufficient. Version, current, upload, and saved result share a shard. The DB transaction does not include remote disks. <a href="#ref-10">[10]</a>')
out+=snippet('publish.pseudo','Pseudocode · PG18 publication')
out+=bi('<code>authorized_result</code> 是 Metadata 对同上传的权威只读查询：重新验证 tenant/bucket/key 权限、owner 和冻结清单摘要后，读取不可变原结果。它不查询 current，也不重新要求旧 payload 存在。合法回收旧版本之后，完成请求仍重放原 version；持久 CONFLICT 同样重放。主事务重新鉴权并检查结果/state/fence，关闭查询与提交之间的竞争。保存请求身份/结果至少覆盖承诺的重试窗口，过期身份必须拒绝而不能当新请求执行。','<code>authorized_result</code> is an authoritative Metadata lookup for this upload: reauthorize the full scope, owner, and frozen manifest hash, then read the immutable original result. It neither resolves current nor requires the old payload to survive. After lawful old-version GC, completion still replays the original version; a durable CONFLICT also replays. The transaction rechecks authorization, result, state, and fence. Retain identities/results throughout the promised retry window; reject expired identities rather than treating them as new operations.')
out+=bi('<strong>两个崩溃窗口：</strong>Data 已耐久、Metadata 未提交，只留下不可见候选；Metadata 已提交、响应丢失，对象已经可见。两者都查询同 upload/operation，未知保持 pending，不换新身份盲传，不用一次空查询授权删除。单键强读依赖共识 Metadata 的权威已提交读与 leader fencing；权威不可达就失败。公开 S3 的原子单键/写后读契约只是接口参考，不证明本示例实现。<a href="#ref-1">[1]</a>','<strong>Two crash windows:</strong> durable Data without Metadata commit leaves an invisible candidate; commit with a lost reply leaves a visible object. Resolve the same upload/operation; uncertainty remains pending. Do not blindly create another identity or authorize cleanup from an empty lookup. Strong point reads need authority reads of committed consensus Metadata and fenced leaders, failing on unavailable authority. Public S3 is an API reference, not proof of this implementation. <a href="#ref-1">[1]</a>')
out+=heading('读取：先授权并固定 manifest，再验证每块','Read: authorize and pin the manifest, then verify every block',3)
out+=bi('GET 的顺序是 <strong>Metadata → Data</strong>。Metadata 在同一代次的事务中解析 current/显式版本、检查权限和可读态、登记带 principal 的 read lease，再返回固定 manifest；GC 的 RECLAIMING 与此过程串行。Data 内部能力必须绑定完整 scope、版本/布局/块、允许范围、GET 操作、受众和期限，校验可信签名与封代次；知道 version_id 或拿到其他租户的 receipt 都不授权读取。','GET runs <strong>Metadata → Data</strong>. One authority transaction resolves current/explicit version, authorizes readability, and registers a principal-bound read lease, serialized against RECLAIMING. Return a pinned manifest. Internal Data grants bind full scope, version/layout/block, allowed range, GET, audience, and expiry, with trusted signatures and fencing. A guessed version id or another tenant’s receipt grants no access.')
out+=bi('下面是 <strong>Java 17 可运行示例中的块校验方法</strong>。Expected 来自已授权的可信 manifest；Identity 含 tenant、bucket、key、version、layout 和 block。每块在交给客户端之前核对身份、长度和 SHA-256；坏副本只触发另一个同版本副本的尝试。不是把副本随字节附的自报 checksum 当权威。<a href="../examples/ch22/VerifiedRead.java">完整类</a>与<a href="../examples/ch22/README.md">运行方式</a>。','This is a <strong>block-verification method from the runnable Java 17 example</strong>. Expected comes from the authorized trusted manifest; Identity includes tenant, bucket, key, version, layout, and block. Verify identity, length, and SHA-256 before releasing a block. A bad replica triggers another replica of the same version, rather than trusting the checksum supplied alongside its bytes. <a href="../examples/ch22/VerifiedRead.java">Full class</a> and <a href="../examples/ch22/README.md">run instructions</a>.')
out+=snippet('VerifiedRead.java','Java 17 · verified block read','runnable','verified-read')
out+=bi('大对象按有界块验证并流式发送，所有块绑定同一 manifest，不能中途重查 current 拼接新版。仅在结束时算整体 hash 无法撤回先前已发字节；因此要逐块可信摘要，接收端仍核对最终长度/整对象摘要并把中断视为不完整传输。CRC32C 可以另作快速偶发损坏检测，既不是身份认证，也不等于整对象 SHA-256；multipart ETag 也不应当作通用 MD5。<a href="#ref-6">[6]</a>','Stream bounded blocks from one pinned manifest; never re-resolve current and splice a newer version. An end-only hash cannot retract bytes already sent. Use trusted block digests and have the recipient verify final length/object digest, treating interruption as an incomplete transfer. CRC32C may provide fast accidental-corruption detection, not authentication or whole-object SHA-256; a multipart ETag is not universal MD5. <a href="#ref-6">[6]</a>')
out+=heading('删除与 GC：先关入口，等持有者排空，再删精确字节','Deletion and GC: close admission, drain holders, delete exact bytes',3)
out+=bi('开启版本保留时，DELETE 发布 delete marker；新的无版本 GET 不存在，仍保留的显式版本按权限可读。它不是销毁旧 payload 的授权。版本保留结束且不再是 current 后，权威先撤销可读引用、变 RECLAIMING 并封代次，拒绝新解析和续租，之前获得的读租约可以完成。A11 的 60 秒是最长单次租期，长读须续租；续租失败就停止。<a href="#ref-9">[9]</a>','With version retention, DELETE publishes a marker: new unversioned GET sees absence, while authorized retained version reads remain possible. It does not authorize payload destruction. Once retention clears and the version is no longer current, authority withdraws readable references, enters RECLAIMING, and fences new resolutions/renewals; preexisting leases may finish. A11’s 60 seconds is a maximum per lease; long reads renew or stop on failure. <a href="#ref-9">[9]</a>')
out+=snippet('gc.pseudo','Pseudocode · fenced cleanup')
out+=bi('未发布候选的十分钟隔离期只减少无效清扫，真正的授权是<strong>同权威状态、无保留引用、过期租约与新 fence</strong>。Data 必须持久关闭旧代次的新写并排空已接收的 writer，之后重复扫尾；旧请求仍可能晚落字节，但已不能注册或发布。若 Data 不确认已排空，就留字节重试。FINALIZING 不可被普通过期扫描接管；专用恢复者只续跑固定清单，需要终止则先在权威显式封代次，不能靠 TTL 猜。','A ten-minute unpublished-candidate quarantine reduces wasted cleanup; authorization comes from <strong>one authority state, no retained references, expired leases, and a new fence</strong>. Data durably closes old-generation writes and drains admitted writers before repeated sweeps. Late bytes cannot register or publish. If drain is unknown, keep bytes and retry. Ordinary expiry scans cannot take FINALIZING; dedicated recovery resumes its fixed manifest or explicitly fences it before termination.')
out+=bi('能力与租约是有限授权：本章允许先前已获租约的读继续至期限。若业务要求 ACL 撤销立即阻断正在读的内容，Data 还需在线撤销检查/权限代次屏障，缓存 ACL 或短有效期本身不能做到。签名直传可把字节从 Client 直接送到 Data，但仍受限于目标、方法、期限和限额，Metadata 最后检查 durable receipt 才发布；这个上传路径是本设计选择，不声称公开 S3 使用相同内部协议。<a href="#ref-11">[11]</a>','Grants and leases are bounded authorization: preexisting reads may continue until expiry. Immediate revocation of ongoing reads requires an online revocation/permission-generation barrier at Data; cached ACLs or short expiry alone cannot deliver it. Direct signed upload can send bytes Client→Data, bounded by target, method, expiry, and quotas; Metadata still verifies durability before publication. This is our design, not a claim about S3 internals. <a href="#ref-11">[11]</a>')
out+='</section>\n'

# Existing secondary mechanisms remain; replace only their decks and specific claims.
for i in range(3,7):
    text=re.sub(r'<figure class="deck">[\s\S]*?</figure>', lambda _: decks[i-2], sections[i], count=1)
    text=text.replace('用规范化后的 bucket_id 与 object key 字节串做 hash','用规范化后的 bucket_id 与未经改写的 object key 原始字节做 hash')
    text=text.replace('Hash normalized bucket id plus exact object-key bytes','Hash the normalized bucket id plus exact, unmodified object-key bytes')
    if i==5:
        text=text.replace('</figure>','</figure>'+bi('左侧收紧后的 Data 框与竖线属于同一服务；竖线只是六组块收发端口，未新增中间组件。故障帧由 Data 本地验证 B0，读 B1–B4 解码，B5 的未用通路淡化；“读四写一”是该次修复，不是健康写的路径数。','The compact Data box and port spine are one service, with no added intermediary. In the fault frame Data locally rejects B0, decodes B1–B4, and leaves unused B5 muted. “Read four, write one” describes this repair, not healthy-write fanout.'),1)
    out+='<section>'+text+'</section>\n'

out+='<section>'+heading('22.6 · Multipart：冻结一份清单，完成与取消争同一状态','22.6 · Multipart: one frozen manifest, one state for completion and abort')+decks[5]
out+=bi('每个 part_number 只表示位置，不足以标识字节。本设计的每次尝试分配新 blob_id，Metadata 条件更新 part_generation；同编号重传先核对旧代次，旧/新 receipt 不能混用。Complete 提交<strong>按编号排序的精确 part 身份清单</strong>，原子冻结为 FINALIZING 后，新的注册、普通 abort 与普通 GC 都不能改选。单 PUT 是只有一个 part 的相同协议。','A part number identifies position, not bytes. Every attempt allocates a fresh blob id; Metadata conditionally advances part_generation. Retrying a number checks its previous generation. Complete supplies an <strong>ordered list of exact part identities</strong> and atomically freezes FINALIZING, blocking reselection by registration, ordinary abort, and ordinary GC. Single PUT uses the same protocol with one part.')
out+=snippet('multipart.pseudo','Pseudocode · freeze and abort')
out+=bi('代码中的唯一/排序和 registered_parts 比较由 Metadata 执行：清单含编号、part_generation、blob_id、长度及摘要，必须等于冻结前已登记集合。本教学契约要求所有已登记编号都在清单中，强于“任选一部分”的协议；Data 检查有序字节的总长与全对象 SHA-256，并确认三副本或六块完整后调用 22.1 发布。同 SHA-256 摘要不等于重用同一操作身份；不同上传也不默认跨用户去重。','Metadata validates ordering/uniqueness and compares numbers, part generations, blob ids, lengths, and digests against the registered set. This teaching contract selects every registered number, stricter than a protocol permitting a subset. Data checks ordered total length and whole-object SHA-256, confirms all three replicas or six fragments, then invokes 22.1 publication. Equal content does not equate request identities or imply cross-user deduplication.')
out+=bi('<strong>恢复不重选：</strong>FINALIZING 的协调者崩溃，恢复者复用同一冻结清单；清单变化就是冲突。FINALIZING 本身不是成功，只有版本、current 与 COMPLETED 原结果同事务才成功；expected_generation 失配则同事务保存 REJECTED/CONFLICT，后续重试不能等前提改变后再成功。完成原结果在旧版本被合法回收后仍可查询，不代表该旧版永远可读。','<strong>Recovery never reselects:</strong> resume the exact frozen manifest after a coordinator crash; a changed manifest conflicts. FINALIZING is not success. Version, current, and saved COMPLETED result commit together; a generation mismatch durably records REJECTED/CONFLICT rather than later succeeding after a precondition change. The original result remains queryable after lawful old-version reclamation, without promising perpetual readability.')
out+=bi('Abort 赢 OPEN 后先封上传代次，返回 ABORTED 只是元数据决定。Data 旧的在途写仍可能完成，先关闭入口并排空，再重复清扫。已完成上传中，未被冻结清单引用的旧尝试也要按不可变 blob_id 单独扫；不能按 part_number 删到新版。共享 pack 只有所有记录的保留引用和读租约都清除才可整体删除，压缩协议见 22.2。','An abort winning OPEN fences the upload; ABORTED is a metadata decision. Old in-flight Data writes may still land: close admission, drain, and sweep repeatedly. Completed uploads also need cleanup of unselected attempts by immutable blob id, not by a reused part-number path. A shared pack is deleted only after all records’ retained references and read leases clear; see 22.2 compaction.')
out+=heading('公开 S3 契约与本设计假设分开','Separate public S3 behavior from this design',3)
out+=bi('S3 允许独立/乱序上传 parts，同编号新上传会替换该编号；complete 按所列编号递增拼装。本设计的 part_generation、FINALIZING、永久原回执和 GC 状态机都是教学方案，不是 S3 内部描述。S3 multipart 自身不因本章的 60 秒租约自动过期；未完成上传须完成、终止或由生命周期清理。<a href="#ref-5">[5]</a>','S3 permits independent/out-of-order part uploads and replaces a previous part at the same number; completion concatenates listed parts in increasing order. Our part generations, FINALIZING, saved-result policy, and GC states are teaching choices, not S3 internals. Public S3 multipart does not automatically expire at our 60-second lease: explicitly finish, stop, or configure lifecycle cleanup. <a href="#ref-5">[5]</a>')
out+=bi('S3 的 AbortMultipartUpload 明确提示：在途 part 仍可能成功，可能需要重复 abort 并用 ListParts 核对为空。CompleteMultipartUpload 的初始 HTTP 200 也可能包含最终错误，直接调用者须解析最终响应，SDK 按其错误语义处理。两者都不能用“看到了 200/发过一次取消”代替最终结果。<a href="#ref-4">[4]</a><a href="#ref-12">[12]</a>','S3 warns that in-flight parts may succeed after abort, requiring repeated aborts and ListParts verification. CompleteMultipartUpload may carry an error after an initial HTTP 200; direct callers must parse the final response, while SDKs apply their error handling. Neither an initial status nor one cancellation request establishes the final outcome. <a href="#ref-4">[4]</a><a href="#ref-12">[12]</a>')
out+=bi('A9：5 GiB÷64 MiB=80 parts，四路理想 20 轮；补一 part 是 1/80=1.25%，不是重新传五 GiB。实际时长仍由带宽和重试决定。一万次中断各留 64 MiB，就是 625 GiB 未发布字节，冗余另乘。按租户限制活跃上传数、未完成字节、续租和 FINALIZING 年龄；同时观测未知结果、坏块/修复年龄与 GC 积压。','A9: 5 GiB/64 MiB gives 80 parts and ideally 20 four-way rounds. Retrying one part sends 1.25%, with real duration bounded by bandwidth/retries. Ten thousand interrupted uploads leaving 64 MiB each consume 625 GiB before redundancy. Limit active uploads, incomplete bytes, renewals, and FINALIZING age per tenant; observe unknown outcomes, corruption/repair age, and GC backlog.')
out+='</section>\n'
out+='<section>'+sections[8]+'</section>\n'
out+='<section><details><summary><span class="lang-zh">八个常见错误：用不变量检查答案</span><span class="lang-en">Eight common mistakes: check the invariants</span></summary>'+re.sub(r'<h2>[\s\S]*?</h2>','',sections[9],count=1)+'</details></section>\n'
refs=sections[10].replace('2026-10-05','2026-10-23')
refs=refs.replace('</ol>','''<li id="ref-9"><a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/DeleteMarker.html">AWS · Working with delete markers</a>, accessed 2026-10-23. <span class="lang-zh">版本桶的简单 DELETE 标记与保留版本；本章租约/GC 是自设协议。</span><span class="lang-en">Versioned simple DELETE markers and retained versions; leases/GC here are our protocol.</span></li>
<li id="ref-10"><a href="https://www.postgresql.org/docs/18/explicit-locking.html">PostgreSQL 18 · Explicit locking</a>. <span class="lang-zh">FOR UPDATE 锁定与事务结束释放；不覆盖 Data。可运行模型是 SQLite 全库写串行化。</span><span class="lang-en">FOR UPDATE locking until transaction end, excluding Data. The runnable model serializes SQLite writers.</span></li>
<li id="ref-11"><a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/using-presigned-url.html">AWS · Presigned URLs</a>, accessed 2026-10-23. <span class="lang-zh">能力权限/期限，非本章 Metadata 发布机制证明。</span><span class="lang-en">Capability permissions/expiry, not proof of our publication mechanism.</span></li>
<li id="ref-12"><a href="https://docs.aws.amazon.com/AmazonS3/latest/API/API_CompleteMultipartUpload.html">AWS · CompleteMultipartUpload</a>, accessed 2026-10-23. <span class="lang-zh">按编号拼接和初始 200 中可能含错误。</span><span class="lang-en">Ordered part concatenation and possible errors embedded after an initial 200.</span></li></ol>''')
out+='<section>'+refs+'</section>\n'
cards=sections[11]
cards=cards.replace('Data durable receipt → Metadata 发布 current 与结果 → API 返回。','Data 完整回执 → Metadata 同事务发布版本/current/原结果 → API 返回；终态重放不再读旧字节。').replace('Data receipt → Metadata commits current/result → API responds.','Complete Data receipt → atomic version/current/result → API response; terminal replay does not reread old bytes.')
cards=cards.replace('都CAS抢OPEN；完成冻结manifest与保存version结果，abort封代次再清。','都争 OPEN；完成冻结精确清单，再同事务发布或保存 CONFLICT。abort 封代次后由 Data 排空再清。').replace('Both CAS OPEN; complete freezes a manifest/saves the version, abort fences then sweeps.','Both compete for OPEN. Complete freezes exact parts and saves publication or CONFLICT; abort fences, then Data drains and sweeps.')
newcards=[('同编号 part 的两个 receipt 都可用吗？','Are two receipts for the same part number interchangeable?','不可。绑定 part_generation/blob_id；Complete 只能冻结当前登记的精确版本。','No. Bind part generation/blob id and freeze exactly the registered version.'),('有 read lease 就能永久读取吗？','Does a read lease allow indefinite reading?','不能。租约绑定 principal/版本/布局/期限，续租失败停止；GC 先拒新租约再等旧租约。','No. Bind principal/version/layout/expiry; stop on failed renewal. GC closes new leases and drains existing ones.'),('S3 Complete 返回初始 200 就完成了吗？','Does an initial S3 Complete HTTP 200 mean success?','不一定。最终响应可能嵌入错误；解析完整结果或使用 SDK 错误处理。','Not necessarily. The final response may embed an error; parse it or use SDK error handling.')]
for zq,eq,za,ea in newcards:
    card=f'<button type="button" class="flip"><span class="q"><span class="lang-zh">{zq}</span><span class="lang-en">{eq}</span></span><span class="a"><span class="lang-zh">{za}</span><span class="lang-en">{ea}</span></span></button>\n'
    cards=cards.rsplit('</div>',1)[0]+card+'</div>'+cards.rsplit('</div>',1)[1]
out+='<section>'+cards+'</section>\n'
out+=baseline[baseline.rindex('</section>')+len('</section>'):]
target.write_text(out)
print('wrote',target,'sha256',hashlib.sha256(target.read_bytes()).hexdigest())
